private String getFieldValue(Form form, FormData formData, String fieldId) {
    Element field = FormUtil.findElement(fieldId, form, formData);
    String[] values = FormUtil.getElementPropertyValues(field, formData);
    return (values != null && values.length > 0) ? values[0] : "";
}

public boolean validate(Element element, FormData formData, String[] values) {
    boolean result = true;
    int count = 0;

    Form form = FormUtil.findRootForm(element);

    // Retrieve form field values

    String email = getFieldValue(form, formData, "email");

    // Correct way to get current record ID


    try {
        // Set up database connection and query
        DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
        Connection con = ds.getConnection();

        PreparedStatement stmt;

            // INSERT case
            stmt = con.prepareStatement(
                "SELECT COUNT(*) FROM dir_user WHERE email = ? "
            );
            stmt.setString(1, email);

        // Execute query and get count
        ResultSet rs = stmt.executeQuery();
        if (rs.next()) {
            count = rs.getInt(1);
        }

    } catch (SQLException e) {
        LogUtil.error("Validation error: Failed to execute database query", e);
        result = false; // Consider invalid if DB error
    }

    LogUtil.warn("count", String.valueOf(count));

    if (count == 0) {
        result = false;
        String id = FormUtil.getElementParameterName(element);
        formData.addFormError(id, "Cette adresse email n’est pas enregistrée.");
    }

    return result;
}

return validate(element, formData, values);

